import express from "express";
import { fileURLToPath } from "node:url";
import { addTask, deleteTask, listTasks, updateTask } from "./db.js";

const publicDir = fileURLToPath(new URL("../public", import.meta.url));

/** Build the Express app around a database, so tests can use an in-memory one. */
export function createApp(db) {
  const app = express();
  app.use(express.json({ limit: "10kb" }));
  app.use(express.static(publicDir));

  app.get("/api/tasks", (req, res) => {
    const { done } = req.query;
    if (done === undefined) return res.json(listTasks(db));
    if (done !== "0" && done !== "1") return res.status(400).json({ error: "done must be 0 or 1" });
    res.json(listTasks(db, Number(done)));
  });

  app.post("/api/tasks", (req, res) => {
    const title = typeof req.body?.title === "string" ? req.body.title.trim() : "";
    if (!title) return res.status(400).json({ error: "title is required" });
    res.status(201).json(addTask(db, title));
  });

  app.patch("/api/tasks/:id", (req, res) => {
    const task = updateTask(db, Number(req.params.id), req.body ?? {});
    if (!task) return res.status(404).json({ error: "not found" });
    res.json(task);
  });

  app.delete("/api/tasks/:id", (req, res) => {
    if (!deleteTask(db, Number(req.params.id))) return res.status(404).json({ error: "not found" });
    res.status(204).end();
  });

  return app;
}

